-- Store schema: catalog, orders, payment events, entitlements, downloads, email log, analytics.
-- Money is integer cents. Times are ISO-8601 UTC text. Ids are random (prefix_xxx) except products, whose id is the
-- public slug from data/products.js. Payment-provider details sit in provider/provider_* columns, so another provider
-- can be added without reshaping orders.

-- Catalog: synced from data/products.js by db/catalog.sql (generated by scripts/build.js). The deploy applies it.
-- sales_paused is the admin's switch and is never touched by the sync.
CREATE TABLE products (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  description TEXT NOT NULL DEFAULT '',
  type TEXT NOT NULL,
  price_cents INTEGER NOT NULL CHECK (price_cents >= 0),
  currency TEXT NOT NULL DEFAULT 'USD',
  artwork TEXT,
  preview TEXT,
  tags TEXT NOT NULL DEFAULT '[]',
  release_id TEXT,
  metadata TEXT NOT NULL DEFAULT '{}',
  featured INTEGER NOT NULL DEFAULT 0,
  published INTEGER NOT NULL DEFAULT 0,
  sales_paused INTEGER NOT NULL DEFAULT 0,
  max_quantity INTEGER NOT NULL DEFAULT 1 CHECK (max_quantity >= 1),
  catalog_hash TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  deleted_at TEXT
);

-- Paid files in the private R2 bucket FILES. r2_key is never sent to browsers.
CREATE TABLE product_files (
  id TEXT PRIMARY KEY,
  product_id TEXT NOT NULL REFERENCES products(id),
  r2_key TEXT NOT NULL UNIQUE,
  filename TEXT NOT NULL,
  label TEXT NOT NULL DEFAULT '',
  content_type TEXT NOT NULL DEFAULT 'application/octet-stream',
  size_bytes INTEGER NOT NULL DEFAULT 0,
  sort INTEGER NOT NULL DEFAULT 0,
  active INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL
);
CREATE INDEX product_files_product ON product_files(product_id, active);

CREATE TABLE orders (
  id TEXT PRIMARY KEY,
  user_id TEXT,
  email TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('pending', 'paid', 'failed', 'refunded', 'cancelled')),
  currency TEXT NOT NULL,
  subtotal_cents INTEGER NOT NULL CHECK (subtotal_cents >= 0),
  discount_cents INTEGER NOT NULL DEFAULT 0 CHECK (discount_cents >= 0),
  total_cents INTEGER NOT NULL CHECK (total_cents >= 0),
  provider TEXT NOT NULL,
  provider_session_id TEXT UNIQUE,
  provider_payment_id TEXT,
  livemode INTEGER NOT NULL DEFAULT 0,
  checkout_url TEXT,
  idempotency_key TEXT UNIQUE,
  access_key_hash TEXT,
  email_key_hash TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  paid_at TEXT,
  closed_at TEXT
);
CREATE INDEX orders_user ON orders(user_id, created_at);
CREATE INDEX orders_email ON orders(email, created_at);
CREATE INDEX orders_payment ON orders(provider, provider_payment_id);

CREATE TABLE order_items (
  id TEXT PRIMARY KEY,
  order_id TEXT NOT NULL REFERENCES orders(id),
  product_id TEXT NOT NULL REFERENCES products(id),
  title TEXT NOT NULL,
  unit_price_cents INTEGER NOT NULL CHECK (unit_price_cents >= 0),
  quantity INTEGER NOT NULL CHECK (quantity >= 1),
  line_total_cents INTEGER NOT NULL CHECK (line_total_cents >= 0),
  UNIQUE (order_id, product_id)
);

-- Every payment-provider event, by its provider id: the duplicate/replay guard and the audit trail.
CREATE TABLE payment_events (
  id TEXT PRIMARY KEY,
  provider TEXT NOT NULL,
  type TEXT NOT NULL,
  order_id TEXT,
  livemode INTEGER NOT NULL DEFAULT 0,
  outcome TEXT NOT NULL,
  detail TEXT,
  received_at TEXT NOT NULL
);
CREATE INDEX payment_events_order ON payment_events(order_id);

-- Ownership, separate from orders: purchases, free claims, promos, manual grants, bundles, subscriptions, replacements.
-- A grant is unique per (product, source, email), so replays never duplicate it. user_id is filled when the email
-- belongs to a verified account (at grant time, or when a guest later verifies that email).
CREATE TABLE entitlements (
  id TEXT PRIMARY KEY,
  user_id TEXT,
  email TEXT NOT NULL,
  product_id TEXT NOT NULL REFERENCES products(id),
  source_type TEXT NOT NULL CHECK (source_type IN ('purchase', 'free', 'promo', 'manual', 'bundle', 'subscription', 'replacement')),
  source_id TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('active', 'revoked')),
  granted_at TEXT NOT NULL,
  expires_at TEXT,
  revoked_at TEXT,
  revoke_reason TEXT,
  note TEXT,
  UNIQUE (product_id, source_type, source_id, email)
);
CREATE INDEX entitlements_user ON entitlements(user_id, status);
CREATE INDEX entitlements_email ON entitlements(email, status);
CREATE INDEX entitlements_source ON entitlements(source_type, source_id);

-- Download audit: issued links, served files, denials. No IP addresses.
CREATE TABLE download_events (
  id TEXT PRIMARY KEY,
  event TEXT NOT NULL CHECK (event IN ('issued', 'served', 'denied')),
  product_id TEXT,
  file_id TEXT,
  entitlement_id TEXT,
  subject TEXT,
  reason TEXT,
  created_at TEXT NOT NULL
);
CREATE INDEX download_events_entitlement ON download_events(entitlement_id);

CREATE TABLE email_events (
  id TEXT PRIMARY KEY,
  kind TEXT NOT NULL,
  to_email TEXT NOT NULL,
  provider TEXT NOT NULL,
  provider_message_id TEXT,
  status TEXT NOT NULL CHECK (status IN ('sent', 'logged', 'failed')),
  dedupe_key TEXT UNIQUE,
  subject TEXT,
  body_text TEXT,
  error TEXT,
  created_at TEXT NOT NULL
);
CREATE INDEX email_events_to ON email_events(to_email, created_at);

-- Privacy-friendly analytics: daily counters only. No cookies, no IPs, no user ids.
CREATE TABLE analytics_daily (
  day TEXT NOT NULL,
  event TEXT NOT NULL,
  subject TEXT NOT NULL DEFAULT '',
  count INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (day, event, subject)
);
